mapper.select:
SELECT sd.id, sd.main_id, sd.sku_id, sd.sku_no, si.warehouse_org_id AS inventoryOrgId, si.warehouse_org_name AS inventoryOrgName, sd.qty AS salesQty, sd.amount AS salesAmount, sd.is_gift, sd.is_close, sd.remark, si.warehouse_id, sd.currency, sd.currency_symbol FROM so_detail sd INNER JOIN so_info si ON sd.main_id = si.id AND sd.is_deleted = FALSE WHERE si.is_deleted = FALSE AND sd.is_close = FALSE
AND si.id = #{id}
AND sd.sku_no IN
#{skuNo}
AND sd.sku_no ILIKE concat('%',#{remoteSearchSku}::text,'%')

SELECT sd.id, sd.main_id, sd.sku_id, sd.sku_no, sd.qty, sd.is_gift, sd.is_close, sd.remark, sd.delivery_status, si.approve_status FROM so_detail sd INNER JOIN so_info si ON sd.main_id = si.id AND sd.is_deleted = FALSE WHERE si.is_deleted=FALSE
AND si.approve_status IN
#{approve}

SELECT tt.main_id, tt.type AS deliveryStatus FROM so_info si INNER JOIN ( SELECT sd.delivery_status AS type, sd.main_id, COUNT(sd.main_id) , t.skuQty AS skuQty FROM so_detail sd LEFT JOIN ( SELECT main_id, COUNT(main_id) skuQty FROM so_detail WHERE is_deleted = false AND is_close = false GROUP BY main_id )t ON sd.main_id = t.main_id WHERE sd.is_deleted = false AND sd.is_close = false GROUP BY sd.delivery_status, sd.main_id,t.skuQty order by sd.delivery_status )tt on si.id = tt.main_id WHERE si.is_deleted = false AND si.approve_status = 'approve' AND CASE WHEN tt.type = 'completeShipment' THEN tt.skuQty = tt.count ELSE 1=1 END
AND tt.type IN
#{deliveryStatus}

SELECT si.approve_status AS type, count(si.id) FROM so_info si WHERE si.is_deleted=FALSE
${permissionSql}
GROUP BY si.approve_status

SELECT tt.type, SUM(CASE WHEN type = 'completeShipment' AND tt.count = tt.skuQty OR (type != 'completeShipment') THEN 1 ELSE 0 END) AS count FROM so_info si INNER JOIN ( SELECT sd.delivery_status AS type, sd.main_id, COUNT(sd.main_id) , t.skuQty AS skuQty FROM so_detail sd LEFT JOIN ( SELECT main_id, COUNT(main_id) skuQty FROM so_detail WHERE is_deleted = FALSE AND is_close = FALSE GROUP BY main_id )t ON sd.main_id = t.main_id WHERE sd.is_deleted = FALSE AND sd.is_close = FALSE GROUP BY sd.delivery_status, sd.main_id,t.skuQty order by sd.delivery_status )tt ON si.id = tt.main_id WHERE si.is_deleted = FALSE AND si.approve_status = 'approve'
${permissionSql}
GROUP BY tt."type"
